export default async function sync({ event, username, password, settings }, context) {
  const p = event.payload,
    s = p.scheduled_event,
    booking = event.event === "invitee.created";
  if (!["invitee.created", "invitee.canceled"].includes(event.event))
    return { result: { ignored: true } };
  const login = await context.fetch("https://api.klicktipp.com/account/login", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ username, password }),
  });
  if (!login.ok) throw Error("KlickTipp login failed");
  const session = await login.json();
  if (!session.sessid || !session.session_name) throw Error("KlickTipp login returned no session");
  const cookie = `${session.session_name}=${session.sessid}`;
  const send = async (data) => {
    let r;
    try {
      r = await context.fetch("https://api.klicktipp.com/subscriber", {
        method: "POST",
        headers: { "Content-Type": "application/json", Cookie: cookie },
        body: JSON.stringify(data),
      });
    } catch {
      throw Error("KlickTipp write result unknown; inspect contacts before retrying");
    }
    if (!r.ok) throw Error("KlickTipp write failed; inspect contacts before retrying");
    return await r.json();
  };
  const tagid = booking ? settings.bookingTagId : settings.cancellationTagId;
  const base = { listid: settings.listId, tagid };
  const mobile = (p.text_reminder_number || "").replace("+", "00").replace(/\s+/g, "");
  const guestField = settings.fields.guests;
  let guests = [],
    fields;
  if (booking) {
    guests = (s.event_guests || []).map((g) => g.email);
    const names = (p.name || "").split(" "),
      f = settings.fields;
    const clock = (v) => {
      const parts = new Intl.DateTimeFormat("en-GB", {
        timeZone: p.timezone,
        hour: "2-digit",
        minute: "2-digit",
        second: "2-digit",
        hourCycle: "h23",
      }).formatToParts(new Date(v));
      const n = Object.fromEntries(parts.map((x) => [x.type, x.value]));
      return Number(n.hour) * 3600 + Number(n.minute) * 60 + Number(n.second);
    };
    fields = {
      fieldFirstName: p.first_name || names.slice(0, -1).join(" "),
      fieldLastName: p.last_name || names.slice(-1).join(""),
      [f.eventName]: s.name,
      [f.joinUrl]: s.location?.join_url || "",
      [f.rescheduleUrl]: p.reschedule_url,
      [f.cancelUrl]: p.cancel_url,
      [f.start]: Math.floor(Date.parse(s.start_time) / 1000),
      [f.end]: Math.floor(Date.parse(s.end_time) / 1000),
      [f.localStart]: Math.floor(
        new Date(
          new Date(s.start_time).toLocaleString("en-US", { timeZone: p.timezone }),
        ).getTime() / 1000,
      ),
      [f.localEnd]: Math.floor(
        new Date(new Date(s.end_time).toLocaleString("en-US", { timeZone: p.timezone })).getTime() /
          1000,
      ),
      [f.startTime]: clock(s.start_time),
      [f.endTime]: clock(s.end_time),
      [f.timezone]: p.timezone,
      [guestField]: JSON.stringify(guests),
    };
  }
  const invitee = await send({
    ...base,
    email: p.email,
    ...(mobile ? { smsnumber: mobile } : {}),
    ...(fields ? { fields } : {}),
  });
  if (!booking) {
    const stored = invitee[guestField] || "";
    if (stored) guests = JSON.parse(stored.replace(/&quot;/g, '"'));
  }
  const written = [];
  for (const email of guests) {
    const guest = await send({
      ...base,
      email,
      ...(fields
        ? {
            fields: Object.fromEntries(
              Object.entries(fields).filter(
                ([key]) => !["fieldFirstName", "fieldLastName", guestField].includes(key),
              ),
            ),
          }
        : {}),
    });
    written.push(guest.id);
  }
  if (!booking && guests.length && !p.rescheduled)
    await send({ ...base, email: p.email, fields: { [guestField]: "" } });
  return { result: { inviteeId: invitee.id, guestIds: written } };
}
